INSERT INTO `products` VALUES (148,_binary '','Computers','High-performance desktop with Intel i9, 32GB RAM, 1TB SSD, perfect for gaming and professional workloads.','products/computers/computers1.png','Orion Titan X1000',2499.99,15,'Desktop','{\"cpu\": \"Intel Core i9-13900K (24-core, 32-thread)\", \"gpu\": \"NVIDIA RTX 4080 16GB\", \"ram\": \"32GB DDR5 5600MHz\", \"storage\": \"1TB NVMe Gen4 SSD\", \"motherboard\": \"Z790 Chipset\", \"psu\": \"850W 80+ Gold\", \"cooling\": \"240mm AIO Liquid Cooling\", \"os\": \"Windows 11 Pro\"}'),(149,_binary '','Computers','Enterprise-grade workstation with dual Xeon processors, 64GB RAM, and NVIDIA RTX A6000, designed for 3D rendering and AI workloads.','products/computers/computers2.png','Quantum Workstation Pro',3999.99,8,'Desktop','{\"cpu\": \"Dual Intel Xeon Silver 4310 (20-core each)\", \"gpu\": \"NVIDIA RTX A6000 48GB\", \"ram\": \"64GB ECC DDR4 3200MHz\", \"storage\": \"2TB NVMe SSD\", \"motherboard\": \"Workstation C621 Chipset\", \"psu\": \"1000W Platinum\", \"os\": \"Windows 11 Pro for Workstations\"}'),(150,_binary '','Computers','Compact yet powerful desktop with AMD Ryzen 9, 32GB RAM, 1TB NVMe SSD, suitable for content creators.','products/computers/computers3.png','CyberCore Element',2199.5,12,'Desktop','{\"cpu\": \"AMD Ryzen 9 7900X (12-core, 24-thread)\", \"gpu\": \"NVIDIA RTX 4070 12GB\", \"ram\": \"32GB DDR5 6000MHz\", \"storage\": \"1TB NVMe Gen4 SSD\", \"motherboard\": \"X670 Chipset\", \"psu\": \"750W 80+ Gold\", \"os\": \"Windows 11 Home\"}'),(151,_binary '','Computers','Gaming powerhouse with overclocked i7, 16GB RAM, 512GB SSD, RGB lighting, ideal for competitive gaming.','products/computers/computers4.png','Titan Edge Pro',1799.99,20,'Desktop','{\"cpu\": \"Intel Core i7-13700K\", \"gpu\": \"NVIDIA RTX 4060 8GB\", \"ram\": \"16GB DDR5 5600MHz\", \"storage\": \"512GB NVMe SSD\", \"cooling\": \"Air Cooling\", \"rgb\": \"Yes\", \"os\": \"Windows 11 Home\"}'),(152,_binary '','Computers','Small form-fac